#include <bits/stdc++.h>
using namespace std;
vector<array<int,8>> solutions;
array<int,8> cur;
bool usedRow[9];
void gen(int col){
    if (col==8){ solutions.push_back(cur); return; }
    for (int r=1;r<=8;r++){
        if (usedRow[r]) continue;
        bool ok=true;
        for (int c=0;c<col;c++) if (abs(cur[c]-r) == abs(c-col)) { ok=false; break; }
        if (!ok) continue;
        usedRow[r]=true;
        cur[col]=r;
        gen(col+1);
        usedRow[r]=false;
    }
}
int main(){
    gen(0);
    int a[8];
    int caseNum=1;
    while (cin >> a[0]) {
        for (int i=1;i<8;i++) cin >> a[i];
        int best=0;
        for (auto &sol : solutions) {
            int match=0;
            for (int i=0;i<8;i++) if (sol[i]==a[i]) match++;
            best = max(best, match);
        }
        cout << "Case " << caseNum++ << ": " << (8-best) << "\n";
    }
}

